            }
            Some("tool") => f.tool_results.push(ToolResultRef {
                call_id: opt_str(m.get("tool_call_id"), "tool_call_id")?,
                name: None,
            }),
            Some("function") => f.tool_results.push(ToolResultRef {
                call_id: None,
                name: opt_str(m.get("name"), "name")?,
