            f.definitions.iter().map(|d| (d.name.as_str(), d.kind)).collect::<Vec<_>>(),
            [("read", ToolCallKind::Function), ("sql", ToolCallKind::Custom), ("old", ToolCallKind::LegacyFunctionCall)]
        );
        assert_eq!(f.prior_calls.len(), 2);
        assert_eq!(
            f.tool_results,
            vec![
                ToolResultRef {
                    call_id: Some("c1".into()),
                    name: None
                },
                ToolResultRef {
