        assert_eq!(out["output"][1]["id"], "msg_paigasus_1");
        assert_eq!(out["output"][1]["content"][0]["text"], "[paigasus] tool call \"read\" was blocked (policy).");
        for k in ["status", "usage", "incomplete_details", "error", "id", "object"] {
            assert_eq!(out[k], v[k], "{k}");
        }
